        d2A_dr2 = _ovec(T, 5)
        dA_dtheta = _ovec(T, 5)
        d2A_dtheta2 = _ovec(T, 5)
        r = x.r
        theta = x.theta
        rp = xp.r
        thetap = xp.theta
        om = M / (a*M + sqrt(M*((rp)^(3))))
        dr = r - rp
        dtheta = theta - thetap
