        d2PhiS_dx2[2] = d2PhiS_dtr*cosmph
        d2PhiS_dx2[3] = - d2PhiS_dtr*sinmph
        d2PhiS_dx2[4] = d2PhiS_dtth*cosmph
        d2PhiS_dx2[5] = - d2PhiS_dtth*sinmph
        d2PhiS_dx2[6] = d2PhiS_dtph*cosmph
        d2PhiS_dx2[7] = - d2PhiS_dtph*sinmph
        d2PhiS_dx2[8] = d2PhiS_dr2*cosmph
        d2PhiS_dx2[9] = - d2PhiS_dr2*sinmph
        d2PhiS_dx2[10] = d2PhiS_drth*cosmph
        d2PhiS_dx2[11] = - d2PhiS_drth*sinmph
        d2PhiS_dx2[12] = d2PhiS_drph*cosmph
        d2PhiS_dx2[13] = - d2PhiS_drph*sinmph
        d2PhiS_dx2[14] = d2PhiS_dth2*cosmph
        d2PhiS_dx2[15] = - d2PhiS_dth2*sinmph
        d2PhiS_dx2[16] = d2PhiS_dthph*cosmph
        d2PhiS_dx2[17] = - d2PhiS_dthph*sinmph
        d2PhiS_dx2[18] = d2PhiS_dph2*cosmph
        d2PhiS_dx2[19] = - d2PhiS_dph2*sinmph
        src[0] = effsrc*cosmph
        src[1] = - effsrc*sinmph
    return (Complex(PhiS[0], PhiS[1]),
            SVector{4,Complex{T}}(Complex(dPhiS_dx[0], dPhiS_dx[1]),
                                  Complex(dPhiS_dx[2], dPhiS_dx[3]),
                                  Complex(dPhiS_dx[4], dPhiS_dx[5]),
                                  Complex(dPhiS_dx[6], dPhiS_dx[7])),
            SVector{10,Complex{T}}(Complex(d2PhiS_dx2[0], d2PhiS_dx2[1]),
                                   Complex(d2PhiS_dx2[2], d2PhiS_dx2[3]),
                                   Complex(d2PhiS_dx2[4], d2PhiS_dx2[5]),
                                   Complex(d2PhiS_dx2[6], d2PhiS_dx2[7]),
                                   Complex(d2PhiS_dx2[8], d2PhiS_dx2[9]),
                                   Complex(d2PhiS_dx2[10], d2PhiS_dx2[11]),
                                   Complex(d2PhiS_dx2[12], d2PhiS_dx2[13]),
                                   Complex(d2PhiS_dx2[14], d2PhiS_dx2[15]),
                                   Complex(d2PhiS_dx2[16], d2PhiS_dx2[17]),
                                   Complex(d2PhiS_dx2[18], d2PhiS_dx2[19])),
            Complex(src[0], src[1]))
end

